import assert from 'node:assert/strict';
import { test } from 'node:test';
import { analyze, configWith } from '../helpers.mjs';

const permissive = configWith({ suppressions: { new: 'allow' } });

function recognizes(fileName, source) {
  const result = analyze(fileName, source, { config: permissive });
  assert.equal(result.status, 'analyzed', `${fileName}: ${result.reason}`);
  return result.findings.length === 0 && result.allowed.some((entry) => entry.category === 'directive' || entry.category === 'suppression');
}

