for (const [family, fixtures] of Object.entries(RECOGNIZED)) {
  test(`recognizes ${family} directives`, () => {
    for (const [fileName, source] of fixtures) assert.ok(recognizes(fileName, source), `${fileName}: ${JSON.stringify(source)}`);
  });
}

const NOT_DIRECTIVES = [
  ['malformed golangci-lint spacing', 'a.go', 'package a\n\nvar x = 1 // nolint:gochecknoglobals\n', 'malformed-directive'],
  ['malformed Go directive spacing', 'a.go', 'package a\n\n// go:generate stringer -type=Pill\n', 'malformed-directive'],
  ['misspelled ESLint directive', 'a.ts', '// eslint-disabled-next-line no-console\nconsole.log(1);\n', 'malformed-directive'],
  ['TypeScript directive with missing dash', 'a.ts', '// @ts ignore\nconst x = 1;\n', 'malformed-directive'],
  ['keyword buried in prose', 'a.ts', '// we should eslint-disable this later\nconst x = 1;\n', null],
  ['unknown Go tool directive', 'a.go', 'package a\n\n//note:explain the loop below\nfunc f() {}\n', null],
  ['webpack-like prose', 'a.js', '/* webpack chunk for charts */\nimport("./chart");\n', null],
  ['pure annotation with prose', 'a.js', '/* pure function */\nconst x = 1;\n', null],
  ['source map lookalike', 'a.js', '// sourceMappingURL explained here\n', null],
  ['RuboCop without colon', 'a.rb', '# rubocop disable Style/Foo\nx = 1\n', 'malformed-directive'],
  ['Dockerfile directive after an instruction', 'Dockerfile', 'FROM alpine\n# syntax=docker/dockerfile:1\n', null],
  ['shellcheck prose', 'a.sh', '# shellcheck complains about this line\necho $x\n', 'malformed-directive'],
];

for (const [name, fileName, source, expectedCode] of NOT_DIRECTIVES) {
  test(`does not treat ${name} as a directive`, () => {
    const result = analyze(fileName, source, { config: permissive });
    assert.equal(result.findings.length, 1, JSON.stringify(result.allowed));
    if (expectedCode) assert.equal(result.findings[0].reasonCode, expectedCode);
  });
}

test('a directive that carries explanatory prose is flagged', () => {
  const result = analyze('a.py', 'x = 1  # fmt: skip # this aligns the matrix columns for readability\n', { config: permissive });
  assert.equal(result.findings[0]?.category, 'directive-prose');
});

test('optional directive sets are opt-in', () => {
  const source = 'struct A {}\n// MARK: - Lifecycle\nfunc a() {}\n';
  assert.equal(analyze('a.swift', source).findings.length, 1);
  const config = configWith({ directives: { custom: [], optional: ['xcode-mark'] } });
  assert.equal(analyze('a.swift', source, { config }).findings.length, 0);
});

test('custom project directives are recognized', () => {
  const config = configWith({ directives: { custom: [{ name: 'licensecheck', pattern: '^licensecheck:(?:skip|ok)$', kind: 'pragma' }], optional: [] } });
  assert.equal(analyze('a.ts', '// licensecheck:skip\nconst x = 1;\n', { config }).findings.length, 0);
  assert.equal(analyze('a.ts', '// licensecheck: explain this\nconst x = 1;\n', { config }).findings.length, 1);
});

test('suppressing a documentation rule is circumvention even when the directive is well formed', () => {
  const result = analyze('a.go', '//lint:file-ignore ST1000 package docs live elsewhere\npackage a\n', { config: permissive });
  assert.equal(result.findings[0]?.reasonCode, 'documentation-circumvention');
});
